using Erp.Abstractions.Events;
namespace Erp.Modules.Inventory;

public enum LocationType { Internal, Supplier, Customer, InventoryLoss, InventoryGain }
public enum StockMoveType { Receipt, Delivery, Transfer, Adjustment }
public enum StockMoveState { Draft, Completed, Cancelled }
public enum ReservationState { Active, Released, Consumed }
public sealed class Warehouse { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid CompanyId { get; set; } public required string Code { get; set; } public required string Name { get; set; } public bool IsActive { get; set; } = true; public required string ConcurrencyStamp { get; set; } public List<StockLocation> Locations { get; set; } = []; }
public sealed class StockLocation { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid CompanyId { get; set; } public Guid? WarehouseId { get; set; } public required string Code { get; set; } public required string Name { get; set; } public LocationType Type { get; set; } public bool IsActive { get; set; } = true; public required string ConcurrencyStamp { get; set; } }
public sealed class StockMove { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid CompanyId { get; set; } public required string Number { get; set; } public StockMoveType Type { get; set; } public StockMoveState State { get; set; } public Guid ProductId { get; set; } public required string ProductSku { get; set; } public required string UnitCode { get; set; } public decimal Quantity { get; set; } public Guid? SourceLocationId { get; set; } public Guid? DestinationLocationId { get; set; } public string? ReferenceDocumentType { get; set; } public Guid? ReferenceDocumentId { get; set; } public DateOnly BusinessDate { get; set; } public string? Notes { get; set; } public Guid? ReversesMoveId { get; set; } public string? CompletionKey { get; set; } public DateTimeOffset CreatedAtUtc { get; set; } public DateTimeOffset? CompletedAtUtc { get; set; } public Guid? CreatedBy { get; set; } public Guid? CompletedBy { get; set; } public required string ConcurrencyStamp { get; set; } }
public sealed class StockReservation { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid CompanyId { get; set; } public Guid ProductId { get; set; } public Guid LocationId { get; set; } public decimal Quantity { get; set; } public decimal ConsumedQuantity { get; set; } public ReservationState State { get; set; } public required string IdempotencyKey { get; set; } public string? ReleaseKey { get; set; } public string? ReferenceDocumentType { get; set; } public Guid? ReferenceDocumentId { get; set; } public DateTimeOffset CreatedAtUtc { get; set; } public DateTimeOffset? ReleasedAtUtc { get; set; } public DateTimeOffset? ConsumedAtUtc { get; set; } public required string ConcurrencyStamp { get; set; } }
public sealed record WarehouseRequest(string? Code, string? Name, bool IsActive = true, string? ConcurrencyStamp = null);
public sealed record WarehouseDto(Guid Id, string Code, string Name, bool IsActive, string ConcurrencyStamp);
public sealed record LocationRequest(Guid? WarehouseId, string? Code, string? Name, LocationType Type, bool IsActive = true, string? ConcurrencyStamp = null);
public sealed record LocationDto(Guid Id, Guid? WarehouseId, string Code, string Name, LocationType Type, bool IsActive, string ConcurrencyStamp);
public sealed record StockMoveRequest(StockMoveType Type, Guid ProductId, decimal Quantity, Guid? SourceLocationId, Guid? DestinationLocationId, DateOnly BusinessDate, string? ReferenceDocumentType = null, Guid? ReferenceDocumentId = null, string? Notes = null, Guid? ReversesMoveId = null);
public sealed record StockMoveBatchLineRequest(Guid ProductId, decimal Quantity);
public sealed record StockMoveBatchRequest(StockMoveType Type, Guid? SourceLocationId, Guid? DestinationLocationId, DateOnly BusinessDate, IReadOnlyList<StockMoveBatchLineRequest>? Lines, string? ReferenceDocumentType = null, Guid? ReferenceDocumentId = null, string? Notes = null);
public sealed record StockMoveBatchDto(IReadOnlyList<StockMoveDto> Items);
public sealed record CompleteMoveRequest(string ConcurrencyStamp, string IdempotencyKey);
public sealed record MoveActionRequest(string ConcurrencyStamp);
public sealed record StockMoveDto(Guid Id, string Number, StockMoveType Type, StockMoveState State, Guid ProductId, string ProductSku, string UnitCode, decimal Quantity, Guid? SourceLocationId, Guid? DestinationLocationId, string? ReferenceDocumentType, Guid? ReferenceDocumentId, DateOnly BusinessDate, string? Notes, Guid? ReversesMoveId, DateTimeOffset CreatedAtUtc, DateTimeOffset? CompletedAtUtc, string ConcurrencyStamp);
public sealed record StockMoveQuery(string? Search = null, Guid? ProductId = null, Guid? WarehouseId = null, Guid? LocationId = null, StockMoveType? Type = null, StockMoveState? State = null, DateOnly? FromDate = null, DateOnly? ToDate = null, string? ReferenceDocumentType = null, Guid? ReferenceDocumentId = null, string Sort = "created", bool Descending = true, int Page = 1, int PageSize = 25);
public sealed record StockMovePage(int Page, int PageSize, int Total, IReadOnlyList<StockMoveDto> Items);
public sealed record ReserveStockRequest(Guid ProductId, Guid LocationId, decimal Quantity, string IdempotencyKey, string? ReferenceDocumentType = null, Guid? ReferenceDocumentId = null);
public sealed record ReservationActionRequest(string ConcurrencyStamp, string IdempotencyKey);
public sealed record ReservationQuery(ReservationState? State = null, Guid? ProductId = null, Guid? LocationId = null, Guid? ReferenceDocumentId = null, int Page = 1, int PageSize = 25);
public sealed record ReservationDto(Guid Id, Guid ProductId, Guid LocationId, decimal Quantity, decimal ConsumedQuantity, decimal RemainingQuantity, ReservationState State, string IdempotencyKey, string? ReferenceDocumentType, Guid? ReferenceDocumentId, DateTimeOffset CreatedAtUtc, DateTimeOffset? ReleasedAtUtc, DateTimeOffset? ConsumedAtUtc, string ConcurrencyStamp);
public sealed record ReservationPage(int Page, int PageSize, int Total, IReadOnlyList<ReservationDto> Items);
public sealed record StockBalanceDto(Guid ProductId, Guid LocationId, decimal OnHand, decimal Reserved, decimal Available);
public sealed record StockBalanceQuery(string? Search = null, Guid? ProductId = null, Guid? WarehouseId = null, Guid? LocationId = null, bool IncludeZero = false, string Sort = "sku", bool Descending = false, int Page = 1, int PageSize = 25);
public sealed record StockBalanceRowDto(Guid ProductId, string ProductSku, string UnitCode, Guid LocationId, string LocationCode, string LocationName, Guid WarehouseId, string WarehouseCode, string WarehouseName, decimal OnHand, decimal Reserved, decimal Available, decimal WarehouseOnHand, decimal WarehouseReserved, decimal WarehouseAvailable);
public sealed record StockBalancePage(int Page, int PageSize, int Total, IReadOnlyList<StockBalanceRowDto> Items);
public sealed class InventoryValidationException(IReadOnlyDictionary<string, string[]> errors) : Exception("Inventory validation failed.") { public IReadOnlyDictionary<string, string[]> Errors { get; } = errors; }
public sealed class InventoryConcurrencyException : Exception { public InventoryConcurrencyException() : base("Inventory changed concurrently.") { } }
public sealed record StockReservedEvent(Guid EventId, DateTimeOffset OccurredAtUtc, Guid ReservationId, Guid ProductId, Guid LocationId, decimal Quantity) : IIntegrationEvent;
public sealed record StockReservationReleasedEvent(Guid EventId, DateTimeOffset OccurredAtUtc, Guid ReservationId, decimal ReleasedQuantity) : IIntegrationEvent;
public sealed record StockReservationConsumedEvent(Guid EventId, DateTimeOffset OccurredAtUtc, Guid ReservationId, Guid MoveId, decimal ConsumedQuantity) : IIntegrationEvent;
public sealed record PurchaseOrderFulfillmentProgressEvent(Guid EventId, DateTimeOffset OccurredAtUtc, Guid PurchaseOrderId, Guid ProductId, decimal OrderedQuantity, decimal ReceivedQuantity, bool IsComplete) : IIntegrationEvent;
public sealed record SalesOrderFulfillmentProgressEvent(Guid EventId, DateTimeOffset OccurredAtUtc, Guid SalesOrderId, Guid ProductId, decimal OrderedQuantity, decimal DeliveredQuantity, bool IsComplete) : IIntegrationEvent;
public sealed record GoodsReceivedEvent(Guid EventId, DateTimeOffset OccurredAtUtc, Guid MoveId, Guid ProductId, Guid LocationId, decimal Quantity, Guid? PurchaseOrderId) : IIntegrationEvent;
public sealed record ShipmentCompletedEvent(Guid EventId, DateTimeOffset OccurredAtUtc, Guid MoveId, Guid ProductId, Guid LocationId, decimal Quantity, Guid? SalesOrderId) : IIntegrationEvent;
public sealed record StockAdjustedEvent(Guid EventId, DateTimeOffset OccurredAtUtc, Guid MoveId, Guid ProductId, decimal Quantity) : IIntegrationEvent;
public sealed record TransferCompletedEvent(Guid EventId, DateTimeOffset OccurredAtUtc, Guid MoveId, Guid ProductId, Guid SourceLocationId, Guid DestinationLocationId, decimal Quantity) : IIntegrationEvent;
